css:
.d-ds2{position:relative;width:100%;max-width:340px;height:190px;border:1px solid var(--line);border-radius:10px;background:var(--paper);overflow:hidden}
.d-ds2-open{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);padding:6px 14px;border:1px solid var(--line);border-radius:999px;background:var(--bg);color:var(--ink);font:inherit;font-size:11px;cursor:pointer}
.d-ds2-sheet{position:absolute;left:0;right:0;bottom:0;height:150px;padding:8px 14px 14px;border-top:1px solid var(--line);border-radius:10px 10px 0 0;background:var(--bg);transform:translateY(102px);transition:transform 280ms var(--ease-physical);touch-action:none;cursor:grab;will-change:transform}
.d-ds2-grip{display:block;width:34px;height:4px;border-radius:999px;background:var(--line);margin:0 auto 8px}
.d-ds2-sheet b{font-size:12px}
.d-ds2-sheet p{margin:2px 0 0;font-size:11px;color:var(--muted)}
.d-ds2-sheet em{position:absolute;right:14px;bottom:10px;font-style:normal;font-family:var(--font-mono);font-size:9px;letter-spacing:.06em;color:var(--faint)}

init:
root => {
  var sheet = root.querySelector('[data-sheet]');
  var open = root.querySelector('[data-open]');
  var state = root.querySelector('[data-state]');
  if (!sheet || !open) return;
  var H = 150, peaks = [102, 52, 0], idx = 0;
  var startY = 0, startT = 0, base = 102, y = 102, dragging = false;
  var apply = function (v, anim) { y = v; sheet.style.transition = anim ? 'transform 280ms cubic-bezier(.34,1.56,.64,1)' : 'none'; sheet.style.transform = 'translateY(' + v + 'px)'; if (state) state.textContent = v === peaks[0] ? 'peek' : v === peaks[1] ? 'half' : 'full'; };
  var nearest = function (v) { var best = 0; peaks.forEach(function (p, i) { if (Math.abs(p - v) < Math.abs(peaks[best] - v)) best = i; }); return best; };
  sheet.addEventListener('pointerdown', function (e) { dragging = true; startY = e.clientY; startT = Date.now(); base = y; sheet.setPointerCapture(e.pointerId); });
  sheet.addEventListener('pointermove', function (e) {
    if (!dragging) return;
    var d = e.clientY - startY;
    var v = base + d;
    if (v < 0) v = v * .25;
    if (v > peaks[0]) v = peaks[0] + (v - peaks[0]) * .3;
    apply(v, false);
  });
  var end = function () { if (!dragging) return; dragging = false; var v = (y - base) / Math.max(1, Date.now() - startT); var i = nearest(y); if (Math.abs(v) > .5) i = Math.max(0, Math.min(2, i + (v > 0 ? 1 : -1))); idx = i; apply(peaks[idx], true); };
  sheet.addEventListener('pointerup', end);
  sheet.addEventListener('pointercancel', end);
  open.addEventListener('click', function () { idx = Math.min(2, idx + 1); apply(peaks[idx], true); });
  apply(102, false);
}
